// gen58.mjs — build targeted base58 probe cases.
// Naive (digit-at-a-time) base58 used only to *aim* probes, never to judge.
import { writeFileSync } from 'node:fs';

const AB = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const B = 58n;

export function utf8(s) { return Array.from(Buffer.from(s, 'utf8')); }
export function bytesToInt(bs) {
  let n = 0n;
  for (const b of bs) n = n * 256n + BigInt(b);
  return n;
}
// naive encode, digit at a time
export function encNaive(bs) {
  let lead = 0;
  while (lead < bs.length && bs[lead] === 0) lead++;
  let n = bytesToInt(bs.slice(lead));
  let s = '';
  while (n > 0n) { const q = n / B; s = AB[Number(n - q * B)] + s; n = q; }
  return AB[0].repeat(lead) + s;
}
export function encStr(s) { return encNaive(utf8(s)); }
// naive decode -> bytes
export function decNaive(s) {
  let lead = 0;
  while (lead < s.length && s[lead] === AB[0]) lead++;
  let n = 0n;
  for (const ch of s.slice(lead)) {
    const i = AB.indexOf(ch);
    if (i < 0) return null;
    n = n * B + BigInt(i);
  }
  const out = [];
  while (n > 0n) { out.unshift(Number(n % 256n)); n = n / 256n; }
  return new Array(lead).fill(0).concat(out);
}
export function digits(s) {
  // number of base58 digits produced by encoding string s
  return encStr(s).length;
}

// ---------------------------------------------------------------- rng
export function rng(seed) {
  let s = BigInt(seed) & 0xffffffffn;
  if (s === 0n) s = 1n;
  return () => {
    s ^= (s << 13n) & 0xffffffffn;
    s ^= s >> 17n;
    s ^= (s << 5n) & 0xffffffffn;
    s &= 0xffffffffn;
    return Number(s) / 4294967296;
  };
}

export function writeCases(path, cases) {
  writeFileSync(path, JSON.stringify(cases));
  return cases.length;
}

